import {content,interests} from './content.js';
import {esc,download,localRead,localWrite} from './core.js';
import {configured,rpc} from './api.js';
const root=document.querySelector('main'),KEY='diagnostic-participant-v1';
let state=localRead(KEY),demo=false,dirty=false,saving=false,error='',saveTimer,stepStart=Date.now();
const stages=['Mes habitudes','Les questions','Premiers défis','Pause','Internet et e-mail','Situations','Mon bilan'];
const pages=[{type:'habits',stage:0},...content.questions.map(q=>({...q,type:'question',stage:1})),...content.challenges.slice(0,3).map(q=>({...q,type:'challenge',stage:2})),{type:'pause',stage:3},...content.challenges.slice(3).map(q=>({...q,type:'challenge',stage:4})),...content.situations.map(q=>({...q,type:'situation',stage:5})),{type:'bilan',stage:6}];
const val=k=>esc(state?.answers?.[k]??'');
function option(name,value,label,type='radio'){const current=state.answers[name];const checked=type==='checkbox'?Array.isArray(current)&&current.includes(value):current===value;return `<label class="option"><input type="${type}" name="${esc(name)}" value="${esc(value)}" ${checked?'checked':''}>${esc(label)}</label>`;}
function field(name,label,area=false){return `<label for="${name}">${label}</label>${area?`<textarea id="${name}" name="${name}" maxlength="2000">${val(name)}</textarea>`:`<input id="${name}" name="${name}" maxlength="200" value="${val(name)}">`}`;}
function persist(){if(demo)return;const ok=localWrite(KEY,state);if(!ok)error='La sauvegarde sur ce poste est indisponible. Gardez cette page ouverte et téléchargez une copie.';}
function changed(){state.revision++;dirty=true;persist();clearTimeout(saveTimer);saveTimer=setTimeout(sync,900);status();}
function status(){const el=document.querySelector('#save-status');if(el)el.textContent=demo?'Démonstration : rien n’est transmis.':error|| (saving?'Enregistrement en cours…':dirty?'Réponses en attente de transmission.':state?.savedAt?'Réponses enregistrées à '+new Date(state.savedAt).toLocaleTimeString('fr-FR'):'');}
async function sync(){if(!state||demo||saving||!dirty)return; saving=true;status();const revision=state.revision;try{await rpc('save_participant',{p_id:state.id,p_secret:state.secret,p_answers:structuredClone(state.answers),p_position:state.position,p_revision:revision,p_finished:!!state.finished});dirty=state.revision!==revision;state.savedAt=new Date().toISOString();state.savedRevision=revision;error='';persist();}catch(e){error=e.message;}finally{saving=false;status();if(dirty&&!error)saveTimer=setTimeout(sync,100);}}
function welcome(){root.innerHTML=`<div class="intro"><p class="eyebrow">Séance de découverte · 1 h 30</p><h1>Faisons le point sur vos usages du numérique</h1><p class="muted">Quelques questions et des exercices pour préparer des ateliers utiles pour vous. Vous pouvez demander de l’aide ou passer une question.</p>${!configured()?'<div class="notice">La collecte des réponses n’est pas encore activée. Vous pouvez découvrir le parcours en démonstration.</div>':''}<form class="card" id="join"><h2>Rejoindre ma séance</h2><div class="form-row"><div><label for="name">Prénom ou pseudonyme</label><input id="name" name="name" maxlength="60" autocomplete="given-name" required></div><div><label for="code">Code donné par l’animateur</label><input id="code" name="code" maxlength="12" autocapitalize="characters" spellcheck="false" required></div></div><p class="muted">Vos réponses seront accessibles à votre animateur pour préparer les ateliers. Aucun compte personnel n’est nécessaire.</p><div id="join-error" role="alert"></div><div class="actions"><button ${!configured()?'disabled':''}>Rejoindre la séance</button><button type="button" class="secondary" id="demo">Essayer la démonstration</button></div></form>${state?`<div class="card"><p>Un parcours est conservé sur cet ordinateur pour <strong>${esc(state.name)}</strong>.</p><div class="actions"><button id="resume">Reprendre ce parcours</button><button class="secondary" id="forget">Effacer la copie sur ce poste</button></div></div>`:''}</div>`;
 document.querySelector('#demo').onclick=()=>{demo=true;start('Démonstration','DEMO');render();};
 document.querySelector('#resume')?.addEventListener('click',()=>{demo=state.demo;dirty=state.savedRevision!==state.revision;render();sync();});
 document.querySelector('#forget')?.addEventListener('click',()=>{if(confirm('Effacer la copie locale ? Les réponses déjà transmises resteront chez votre animateur.')){localStorage.removeItem(KEY);state=null;welcome();}});
 document.querySelector('#join').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const f=new FormData(e.target);const name=f.get('name').trim(),code=f.get('code').trim().toUpperCase();try{if(!name)throw Error('Indiquez votre prénom ou un pseudonyme.');const next={id:crypto.randomUUID(),secret:crypto.randomUUID()+crypto.randomUUID()};await rpc('join_session',{p_code:code,p_name:name,p_id:next.id,p_secret:next.secret});demo=false;start(name,code,next);render();changed();}catch(err){document.querySelector('#join-error').textContent=err.message;button.disabled=false;}};
}
function start(name,code,ids={id:crypto.randomUUID(),secret:''}){state={...ids,name,code,demo,position:0,answers:{},revision:0,savedRevision:-1,startedAt:new Date().toISOString()};dirty=!demo;error='';persist();}
function currentHtml(p){if(p.type==='question')return `<p class="number">${p.id} · ${esc(p.theme)}</p><h1 class="question" id="page-title" tabindex="-1">${esc(p.q)}</h1><fieldset><legend class="muted">Choisissez une réponse.</legend>${p.options.map((o,i)=>option(p.id,'ABCD'[i],o)).join('')}${option(p.id,'NSP','Je ne sais pas')}</fieldset>`;
 if(p.type==='challenge')return `<div class="split"><p class="eyebrow">${p.id} · À faire sur l’ordinateur</p><span class="pill">Repère : ${p.time} min</span></div><h1 id="page-title" tabindex="-1">${esc(p.title)}</h1><ol class="exercise">${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${p.id==='D1'?'<p><a href="./Depart.txt" download>Télécharger Depart.txt si l’animateur ne l’a pas déjà installé</a></p>':''}${['D5','D6'].includes(p.id)?'<p><a href="./entrainement.html" target="_blank" rel="noopener">Ouvrir la page d’exercice dans un autre onglet</a></p>':''}${p.id==='D4'?field('D4_commune','Commune')+field('D4_horaire','Horaire trouvé')+field('D4_source','Adresse de la page'):''}<fieldset><legend>Comment cela s’est-il passé ?</legend>${['Réalisé seul','Réalisé avec aide','Essayé sans terminer','Non tenté'].map(o=>option(p.id,o,o)).join('')}</fieldset>${field(p.id+'_note','Une difficulté ou une remarque ? (facultatif)',true)}<p class="muted">L’animateur pourra observer votre réalisation. Le temps n’est pas une note.</p>`;
 if(p.type==='situation')return `<p class="eyebrow">${p.id} · Situation du quotidien</p><h1 id="page-title" tabindex="-1">${esc(p.title)}</h1><p>${esc(p.text)}</p>${field(p.id,'Que feriez-vous ?',true)}<p class="muted">Vous pouvez aussi demander à répondre à l’oral.</p>`;
 if(p.type==='pause')return '<p class="eyebrow">À mi-parcours</p><h1 id="page-title" tabindex="-1">Une pause de 5 minutes</h1><p>Vous reprendrez ensuite avec Internet et la préparation d’un e-mail.</p><p>Gardez cette page ouverte. L’animateur vous indiquera quand continuer.</p>';
 if(p.type==='habits')return `<p class="eyebrow">Accueil · 10 minutes avec l’animateur</p><h1 id="page-title" tabindex="-1">Vos habitudes</h1><fieldset><legend>Quels appareils utilisez-vous ?</legend>${['Ordinateur','Smartphone','Tablette','Aucun'].map(o=>option('devices',o,o,'checkbox')).join('')}</fieldset><fieldset><legend>Avez-vous Internet chez vous ?</legend>${['Oui','Non','Je ne sais pas'].map(o=>option('internet',o,o)).join('')}</fieldset>${field('already','Une chose que vous faites déjà seul',true)}${field('help','Une chose pour laquelle vous demandez de l’aide',true)}`;
 return `<p class="eyebrow">Bilan · 10 minutes avec l’animateur</p><h1 id="page-title" tabindex="-1">Vos envies pour la suite</h1><fieldset><legend>Choisissez jusqu’à trois sujets utiles pour vous.</legend>${interests.map(o=>option('interests',o,o,'checkbox')).join('')}</fieldset>${field('other_interest','Un autre sujet ?')}${field('success','Aujourd’hui, vous avez réussi à…',true)}${field('goal','Votre objectif pour les ateliers',true)}`;
}
function render(focus=false){if(state.finished){finishScreen();return;}const p=pages[state.position];stepStart=Date.now();root.innerHTML=`<div class="layout"><aside class="steps"><p class="eyebrow">${esc(state.name)}</p><p>${demo?'Démonstration':'Séance '+esc(state.code)}</p><progress value="${state.position}" max="${pages.length}"></progress><p class="number">Étape ${state.position+1} sur ${pages.length}</p><ol>${stages.map((s,i)=>`<li class="${i===p.stage?'active':i<p.stage?'done':''}">${s}</li>`).join('')}</ol><button class="small secondary" id="backup">Télécharger une copie</button></aside><section><div class="card">${currentHtml(p)}<div id="limit-error" role="alert"></div><div class="actions"><button class="secondary" id="prev" ${state.position===0?'disabled':''}>Précédent</button><button id="next">${state.position===pages.length-1?'Terminer et transmettre':'Continuer'}</button></div></div><p class="status" id="save-status" role="status" aria-live="polite"></p><button id="retry" class="small secondary">Réessayer l’enregistrement</button></section></div>`;
 document.querySelectorAll('input,textarea').forEach(el=>el.addEventListener('input',()=>{const name=el.name;if(el.type==='checkbox'){const checked=[...document.querySelectorAll(`input[name="${name}"]:checked`)];if(name==='interests'&&checked.length>3){el.checked=false;document.querySelector('#limit-error').textContent='Choisissez au maximum trois sujets.';return;}state.answers[name]=checked.map(c=>c.value);}else state.answers[name]=el.value;changed();}));
 document.querySelector('#prev').onclick=()=>navigate(-1);document.querySelector('#next').onclick=()=>navigate(1);document.querySelector('#retry').onclick=()=>{error='';sync();};document.querySelector('#backup').onclick=backup;status();if(focus){document.querySelector('#page-title').focus();window.scrollTo(0,0);}}
function navigate(delta){const p=pages[state.position];const key=p.id||p.type;state.answers._time={...state.answers._time,[key]:Math.round((state.answers._time?.[key]||0)+(Date.now()-stepStart)/1000)};if(delta===1&&state.position===pages.length-1){state.finished=true;changed();render();sync();return;}state.position=Math.max(0,Math.min(pages.length-1,state.position+delta));changed();render(true);}
function backup(){const {secret,...safe}=state;download('diagnostic-'+state.id+'.json',JSON.stringify(safe,null,2),'application/json');}
function finishScreen(){root.innerHTML=`<div class="narrow"><p class="eyebrow">Parcours terminé</p><h1>Merci pour vos réponses</h1><div class="card"><p>Vos réponses aideront l’animateur à préparer les prochains ateliers.</p><p id="save-status" class="status" role="status" aria-live="polite"></p><p>Avant de fermer cette page, vérifiez que les réponses sont bien enregistrées.</p><div class="actions"><button id="retry">Vérifier la transmission</button><button class="secondary" id="backup">Télécharger une copie</button><button class="secondary" id="edit">Revoir mes réponses</button></div></div><a href="./">Retour à l’accueil</a></div>`;document.querySelector('#retry').onclick=()=>{error='';dirty=true;sync();};document.querySelector('#backup').onclick=backup;document.querySelector('#edit').onclick=()=>{state.finished=false;changed();render();};status();}
window.addEventListener('online',()=>{error='';sync();});window.addEventListener('beforeunload',e=>{if(dirty&&!demo){e.preventDefault();e.returnValue='';}});setInterval(()=>{if(dirty&&!demo)sync();},15000);welcome();
